/bin/bash -lc "python3 - <<'PY'
from PIL import Image
im=Image.open('first_frame.png')
# crops around tool, cup, liquid
crops={
 'tool':(80,0,150,75),
 'cup':(75,35,170,143),
 'liquid':(90,45,155,90),
 'full2x':(0,0,256,144),
}
for name,box in crops.items():
    c=im.crop(box)
    if name=='full2x': c=c.resize((512,288),Image.Resampling.NEAREST)
    else: c=c.resize((c.width*5,c.height*5),Image.Resampling.NEAREST)
    c.save(f'.tmp/{name}.png')
PY"

